query_syntax.clean_status_table:
DECLARE
    last_cleanup_time TIMESTAMP_NTZ;
    timestamp_now TIMESTAMP_NTZ;
BEGIN
    last_cleanup_time := (SELECT MAX(${QO}status_time${QC}) FROM ${QO}${TABLE_OWNER}${QC}.${QO}${TABLE_NAME}${QC} WHERE ${QO}task_name${QC} = '${LAST_CLEANUP_TIME_ENTRY_NAME}');
    timestamp_now := CURRENT_TIMESTAMP();
    IF ((last_cleanup_time IS NULL) OR (timestamp_now > TIMESTAMPADD('minute', ${CLEANUP_INTERVAL}, last_cleanup_time))) THEN
        INSERT INTO ${QO}${TABLE_OWNER}${QC}.${QO}${TABLE_NAME}${QC}(${QO}server_name${QC}, ${QO}task_name${QC}, ${QO}status_time${QC}) VALUES('${LAST_CLEANUP_TIME_ENTRY_NAME}', '${LAST_CLEANUP_TIME_ENTRY_NAME}', :timestamp_now);
        COMMIT;
        DELETE FROM ${QO}${TABLE_OWNER}${QC}.${QO}${TABLE_NAME}${QC} WHERE (${QO}server_name${QC}, ${QO}task_name${QC}, ${QO}status_time${QC}) NOT IN (SELECT ${QO}server_name${QC}, ${QO}task_name${QC}, MAX(${QO}status_time${QC}) FROM ${QO}${TABLE_OWNER}${QC}.${QO}${TABLE_NAME}${QC} GROUP BY ${QO}server_name${QC}, ${QO}task_name${QC});
        COMMIT;
    END IF;
    EXCEPTION WHEN STATEMENT_ERROR THEN
        // if the error is not 'Your statement was aborted because the number of waiters for this lock exceeds the 20 statements limit.'
        IF (NOT(sqlcode = 625 AND sqlstate = 57014)) THEN
            RAISE;
        END IF;
END;

